import random

def sample(scores: dict[str, float], temperature: float) -> str:
    if temperature == 0:
        return max(scores, key=scores.get)
    weights = [v ** (1 / temperature) for v in scores.values()]
    return random.choices(list(scores), weights=weights, k=1)[0]

scores = {"clair": 0.55, "précis": 0.30, "créatif": 0.15}
print(sample(scores, temperature=0))    # toujours "clair" : reproductible pour les tests
print(sample(scores, temperature=0.9))  # varie d'une exécution à l'autre
